package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var LedgerFile *os.File
var ledgerReader *bufio.Scanner
var ledgerRec LedgerRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func truncateAndOverflow(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// truncate toward zero to scale
	v = v.Truncate(scale)
	// drop high-order digits if overflow
	limit := decimal.New(1, intDigits+int(scale)) // 10^(intDigits+scale)
	scaled := v.Shift(scale) // integer
	if scaled.Abs().GreaterThanOrEqual(limit) {
		absMod := scaled.Abs().Mod(limit)
		if scaled.Sign() < 0 {
			scaled = absMod.Neg()
		} else {
			scaled = absMod
		}
		v = scaled.Shift(-scale)
	}
	return v
}

func storeWsBal(v decimal.Decimal) {
	WsBal = truncateAndOverflow(v, 7, 2)
}
func storeWsBranchTot(v decimal.Decimal) {
	WsBranchTot = truncateAndOverflow(v, 9, 2)
}
func storeWsGrandTot(v decimal.Decimal) {
	WsGrandTot = truncateAndOverflow(v, 9, 2)
}

func formatNumericEdited(v decimal.Decimal, picture string) string {
	// determine width = len(picture)
	width := len(picture)
	hasSign := strings.HasPrefix(picture, "-") || strings.HasPrefix(picture, "+")
	picCore := picture
	signPlaceholder := ""
	if hasSign {
		signPlaceholder = picture[0:1]
		picCore = picture[1:]
	}
	// split integer / fractional parts of picture core
	dotIdx := strings.Index(picCore, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picCore[:dotIdx]
		fracPic = picCore[dotIdx+1:]
	} else {
		intPic = picCore
		fracPic = ""
	}
	fracDigits := len(fracPic) // count of 9/Z in fraction (assuming all 9)
	// count digit placeholders in integer part
	intPlaceholders := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPlaceholders++
		}
	}
	// prepare sign char
	isNeg := v.Sign() < 0
	signChar := " "
	if hasSign {
		if isNeg {
			signChar = "-"
		} else {
			signChar = " "
		}
		if signPlaceholder == "+" {
			if isNeg {
				signChar = "-"
			} else {
				signChar = "+"
			}
		}
	}
	absVal := v.Abs()
	// truncate (not round) to fracDigits for display? MOVE does truncation already but format should round? No, just represent value.
	// Ensure scale
	absVal = absVal.Truncate(int32(fracDigits))
	// get integer part and fractional part digits
	// Use Shift to get integer representation
	scaledAbs := absVal.Shift(int32(fracDigits)) // integer
	// integer string of scaled absolute value, zero padded
	// fractional digits are last fracDigits of scaled
	scaledStr := scaledAbs.BigInt().String() // no sign
	// pad leading zeros to at least fracDigits+1
	if len(scaledStr) <= fracDigits {
		scaledStr = strings.Repeat("0", fracDigits+1-len(scaledStr)) + scaledStr
	}
	var intStr string
	var fracStr string
	if fracDigits > 0 {
		intStr = scaledStr[:len(scaledStr)-fracDigits]
		fracStr = scaledStr[len(scaledStr)-fracDigits:]
	} else {
		intStr = scaledStr
		fracStr = ""
	}
	// handle overflow dropping high-order integer digits
	if len(intStr) > intPlaceholders {
		intStr = intStr[len(intStr)-intPlaceholders:]
	} else if len(intStr) < intPlaceholders {
		intStr = strings.Repeat("0", intPlaceholders-len(intStr)) + intStr
	}
	// Now build integer formatted part with commas according spec positions
	// Map placeholders to characters in intPic
	// We need to walk intPic and consume intStr digits in order
	// Build result slice for integer part
	intDigitsConsumed := 0
	intResult := make([]byte, len(intPic))
	// Also need to know which positions are Z for suppression
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			intResult[i] = intStr[intDigitsConsumed]
			intDigitsConsumed++
		} else {
			// comma or other literal
			intResult[i] = byte(c)
		}
	}
	// Z-suppression: leading zeros become spaces
	// Find last placeholder index that is still in leading zero zone
	// We suppress consecutive leading Z placeholders that are '0', and commas between them become spaces
	suppressing := true
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' {
			if suppressing && intResult[i] == '0' {
				intResult[i] = ' '
			} else {
				suppressing = false
			}
		} else if c == '9' {
			suppressing = false
		} else if c == ',' {
			if suppressing {
				// check if all Z placeholders before next non-comma are still suppressed?
				// In COBOL, comma inside suppressed zone becomes space.
				// We already are in suppressing zone, so make it space.
				intResult[i] = ' '
			}
		} else {
			// other literal
		}
		// Once suppressing becomes false, keep rest as is
		if !suppressing && c != ',' && c != '.' {
			// ensure we don't incorrectly keep suppressing after a non-zero Z
			// Need to continue but not revert
		}
	}
	// But we need to handle case where all integer digits are zero: the last digit before decimal should remain '0'
	// Our loop would have turned the last Z that is zero into space if intPlaceholders>1 and value is zero.
	// COBOL rule: at least the digit immediately left of decimal point (the '9') stays.
	// Since we only turn Z's to space, and there's a final '9', that case is handled: last placeholder is '9' and stays '0'.
	// For pictures like ZZ,ZZ9, integer placeholders are Z Z , Z Z 9 -> last is 9, so zero prints as "        0"
	// Works.

	intPartFormatted := string(intResult)

	var core string
	if fracDigits > 0 {
		core = intPartFormatted + "." + fracStr
	} else {
		core = intPartFormatted
	}
	if hasSign {
		core = signChar + core
	}
	// Ensure width (should already be)
	if len(core) < width {
		core = strings.Repeat(" ", width-len(core)) + core
	} else if len(core) > width {
		core = core[len(core)-width:]
	}
	return core
}

func formatAmt(v decimal.Decimal) string {
	return formatNumericEdited(v, "ZZ,ZZ9.99")
}
func formatBal(v decimal.Decimal) string {
	return formatNumericEdited(v, "-Z,ZZZ,ZZ9.99")
}
func formatTot(v decimal.Decimal) string {
	return formatNumericEdited(v, "-ZZZ,ZZZ,ZZ9.99")
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseLedgerLine(line string) LedgerRec {
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	}
	if len(line) > 14 {
		line = line[:14]
	}
	brBranch := line[0:2]
	brAcct := line[2:6]
	brType := line[6:7]
	amtStr := line[7:14]
	amtStrTrim := strings.TrimSpace(amtStr)
	var amt decimal.Decimal
	if amtStrTrim == "" {
		amt = decimal.NewFromInt(0)
	} else {
		// amt field is digits only, may contain spaces? treat non-digit as 0?
		clean := ""
		for _, ch := range amtStrTrim {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			}
		}
		if clean == "" {
			amt = decimal.NewFromInt(0)
		} else {
			bi, _ := decimal.NewFromString(clean)
			// implied V99
			amt = bi.Shift(-2)
		}
	}
	return LedgerRec{BrBranch: brBranch, BrAcct: brAcct, BrType: brType, BrAmt: amt}
}

func mainPara() {
	var err error
	LedgerFile, err = os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty
		WsEofFlag = "Y"
		ledgerReader = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer LedgerFile.Close()
		ledgerReader = bufio.NewScanner(LedgerFile)
		// allow long lines
		ledgerReader.Buffer(make([]byte, 0, 64*1024), 64*1024)
	}
	readPara()
	for !isInputDone() {
		processPara()
	}
	if !isFirstRecord() {
		acctBreakPara()
		branchBreakPara()
	}
	// CLOSE handled via defer
	grandPara()
}

func readPara() {
	if ledgerReader.Scan() {
		line := ledgerReader.Text()
		// Do not trim trailing spaces that are significant? Scanner strips newline but keeps other spaces.
		// However Scanner trims? It returns line without trailing \r\n, but keeps spaces? bufio.Scanner keeps all except newline.
		// Need to handle that input.dat may have no trailing spaces; we pad anyway.
		rec := parseLedgerLine(line)
		ledgerRec = rec
	} else {
		WsEofFlag = "Y"
	}
}

func processPara() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			acctBreakPara()
			branchBreakPara()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				acctBreakPara()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	postPara()
	readPara()
}

func postPara() {
	WsAmtEd = formatAmt(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		storeWsBal(WsBal.Add(ledgerRec.BrAmt))
		fmt.Printf("%s D %s\n", ledgerRec.BrAcct, WsAmtEd)
	case "C":
		storeWsBal(WsBal.Sub(ledgerRec.BrAmt))
		fmt.Printf("%s C %s\n", ledgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		// PIC 99 overflow truncated to 2 digits
		WsSkipped = WsSkipped % 100
		fmt.Printf("%s ? SKIPPED\n", ledgerRec.BrAcct)
	}
}

func acctBreakPara() {
	WsBalEd = formatBal(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	storeWsBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func branchBreakPara() {
	WsTotEd = formatTot(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	storeWsGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func grandPara() {
	WsTotEd = formatTot(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	// WS-SKIPPED display: PIC 99 zero-padded width 2
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	fmt.Printf("SKIPPED: %s\n", skippedStr)
}

func main() {
	mainPara()
}

